def experiment(inputs):
    history = inputs.get('history', [])
    valid_count = 0
    for t in history:
        # Strict schema gate: only allow valid dicts with known keys
        if isinstance(t, dict) and 'transition_id' in t:
            valid_count += 1
        else:
            # Reject invalid state
            return 0.0
    return 1.0 if len(history) > 0 else 1.0

def experiment(inputs):
    history = inputs.get('history', [])
    results = []
    for t in history:
        # Ensure we strictly type-check to avoid invalid measurements
        if isinstance(t, dict) and 'transition_id' in t:
            results.append(1.0)
        elif t is None:
            results.append(1.0)
        else:
            results.append(0.0)
    return {'verification_accuracy': sum(results) / len(results) if len(results) > 0 else 0.0}
